mapper.select:
	    SELECT *
	      FROM (
	        SELECT DISTINCT

	          FROM TB_INTG_SCHD S
          LEFT JOIN TB_EMPLOYEE WE   ON WE.EMP_ID    = S.SCHD_WRTR_ID
		  LEFT JOIN TB_DEPARTMENT WD  ON WD.DEPT_CD   = WE.DEPT_CD
	      LEFT JOIN TB_JOB_GRADE WJG  ON WJG.JOB_GRD_CD = WE.JOB_GRD_CD
	         WHERE 
	           AND S.BEGIN_DT <= #{endDt}
	           AND S.END_DT   >= #{beginDt}
	           AND (
	                 S.SCHD_WRTR_ID = #{empId}
	                 OR S.SCHD_ID IN (
	                     SELECT T.SCHD_ID
	                       FROM TB_SCHD_TARGET T
	                      WHERE (T.TARGET_TYPE_CD = '01')
	                         OR (T.TARGET_TYPE_CD = '02' AND T.TARGET_ID = TO_CHAR(#{empId}))
	                         OR (T.TARGET_TYPE_CD = '04' AND T.TARGET_ID = #{deptCd})

	                             OR (T.TARGET_TYPE_CD = '03')


	                             OR (T.TARGET_TYPE_CD = '05' AND T.TARGET_ID IN

	                                     #{projId}

	                             )


	                             OR (T.TARGET_TYPE_CD = '06' AND T.TARGET_ID IN

	                                     #{taskId}

	                             )

	                 )
	               )
	         ORDER BY S.BEGIN_DT ASC
	      )

	    WHERE ROWNUM <= #{limit}

SELECT * FROM ( SELECT S.SCHD_ID AS id, S.SCHD_CLSF_CD AS scheduleTypeCode, S.SCHD_NM AS title, S.BEGIN_DT AS startDt, S.END_DT AS endDt, S.ALL_DAY_YN AS allDayYn, MAX(D.DEPT_NM) AS deptNm, MAX(P.PROJ_NM) AS projNm, MAX(T.TASK_NM) AS taskNm FROM TB_INTG_SCHD S LEFT JOIN TB_SCHD_TARGET TD ON TD.SCHD_ID = S.SCHD_ID AND TD.TARGET_TYPE_CD = '04' LEFT JOIN TB_DEPARTMENT D ON D.DEPT_CD = TD.TARGET_ID LEFT JOIN TB_SCHD_TARGET TP ON TP.SCHD_ID = S.SCHD_ID AND TP.TARGET_TYPE_CD = '05' LEFT JOIN TB_PROJECT P ON P.PROJ_ID = TO_NUMBER(TP.TARGET_ID) LEFT JOIN TB_SCHD_TARGET TT ON TT.SCHD_ID = S.SCHD_ID AND TT.TARGET_TYPE_CD = '06' LEFT JOIN TB_TASK T ON T.TASK_ID = TO_NUMBER(TT.TARGET_ID) WHERE S.DEL_YN = 'N' AND S.BEGIN_DT <= #{endDt} AND S.END_DT >= #{beginDt} AND ( S.SCHD_WRTR_ID = #{empId} OR S.SCHD_ID IN ( SELECT T2.SCHD_ID FROM TB_SCHD_TARGET T2 WHERE (T2.TARGET_TYPE_CD = '01') OR (T2.TARGET_TYPE_CD = '02' AND T2.TARGET_ID = TO_CHAR(#{empId})) OR (T2.TARGET_TYPE_CD = '04' AND T2.TARGET_ID = #{deptCd})
OR (T2.TARGET_TYPE_CD = '03')
) ) GROUP BY S.SCHD_ID, S.SCHD_CLSF_CD, S.SCHD_NM, S.BEGIN_DT, S.END_DT, S.ALL_DAY_YN ORDER BY S.BEGIN_DT ASC ) WHERE ROWNUM <= #{limit}
